    static func first(_ values: String?...) -> String {
        for value in values {
            if let value, !value.isEmpty { return value }
        }
        return ""
    }

    static func toTraditional(_ simplified: String) -> String {
        String(simplified.map { char in
            if let mapped = s2t[char], let first = mapped.first { return first }
            return char
        })
    }

